update public.products set description='Whole frozen broiler chicken with tender meat suitable for roasting, boiling, frying, grilling, soups, stews and other chicken dishes.', handling_protocols=array['Keep frozen until ready to thaw and keep raw poultry separated from ready-to-eat foods.','Do not wash raw chicken; clean hands, knives, boards and surfaces thoroughly after handling.','Thaw safely in the refrigerator where possible and never on a kitchen counter.','Cook the thickest part to at least 74°C / 165°F.']::text[], storage_tips=array['Keep continuously frozen at approximately -18°C or below.','For best quality, use within about 6–12 months.','After refrigerator thawing, cook within 1–2 days.','Do not refreeze chicken that has been left warm for an unsafe period.']::text[] where name='Frozen Broiler Chicken' and category_id=(select id from public.product_categories where name='Meat & Poultry');
update public.products set description='Whole processed broiler chicken with tender meat suitable for frying, grilling, roasting, boiling, soups, stews and a wide range of everyday chicken dishes.', handling_protocols=array['Keep raw chicken cold and separated from produce, cooked foods and other ready-to-eat foods.','Do not wash raw chicken; clean hands, utensils and preparation surfaces thoroughly after handling.','Cook the thickest part of the bird to at least 74°C / 165°F.']::text[], storage_tips=array['If supplied chilled, refrigerate at 4°C or below and use within 1–2 days.','If it will not be cooked promptly, freeze at about -18°C or below.','For best frozen quality, use within about 6–12 months.','In hot conditions above 32°C, do not leave raw poultry unrefrigerated for more than about 1 hour.']::text[] where name='Processed Broiler Chicken' and category_id=(select id from public.product_categories where name='Meat & Poultry');
update public.products set description='Whole processed spent-layer chicken, commonly called old-layer chicken, with firmer meat than a young broiler and well suited to soups, stews, pepper soup and other longer-cooked dishes.', handling_protocols=array['Treat as raw poultry and keep cold and separated from ready-to-eat foods.','Do not wash the raw carcass before cooking; clean hands and surfaces after handling.','Cook the meat to at least 74°C / 165°F; longer cooking may improve tenderness.']::text[], storage_tips=array['If supplied chilled, refrigerate at 4°C or below and use within 1–2 days.','If supplied frozen, keep at about -18°C or below.','For best frozen quality, use within about 6–12 months.']::text[] where name='Processed Spent Layer Chicken' and category_id=(select id from public.product_categories where name='Meat & Poultry');;
